INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10001','退换货','Apple 中国大陆官方商店退货政策','苹果 Apple iPhone iPad MacBook AirPods 退货 退款 换货 无理由 激活 原包装','Apple Store 对符合条件的商品提供交付之日起 14 个自然日内的退货申请窗口。iPhone/iPad 退回时须完好，并带齐原包装、配件与说明材料。请从原 Apple 订单发起申请，核对具体产品限制；不能将此窗口套用到第三方商城订单。','APPLE','RETURNS','apple-returns','https://www.apple.com.cn/shop/help/returns_refund','Apple 中国大陆官方商店退货政策','2026-11-17','中国大陆 Apple Store 在线商店对应订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10002','退款','Apple 官方商店退款处理说明','Apple 苹果 退款 到账 原路 支付','符合退货条件并按官方流程退回商品后，退款按对应支付方式办理。退款处理与银行卡或支付账户实际到账不是同一时点，需核对 Apple 原订单与支付机构处理情况；本地摘要不承诺统一到账天数。','APPLE','REFUND','apple-refund','https://www.apple.com.cn/shop/help/returns_refund','Apple 官方商店退款处理说明','2026-11-17','中国大陆 Apple Store 在线商店对应订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10003','保修','Apple 中国大陆有限保修参考','Apple 苹果 保修 质保 维修 三包 硬件','该文档为 Apple 一年有限保修条款，并明确法定消费者权利不被该保修排除。适用品类、购买日期、材料或工艺缺陷及例外条件必须按具体条款核对；不能将单篇条款外推为所有 Apple 商品、主要部件或 AppleCare 服务的统一期限。','APPLE','WARRANTY','apple-warranty','https://www.apple.com.cn/legal/warranty/products/warranty-china.html','Apple 中国大陆有限保修参考','2026-11-17','文档列明的 Apple 品牌硬件及适用保修版本','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10004','配送','Apple 官方商店发货与交货','Apple 苹果 配送 发货 快递 运费 包邮','Apple 在线订单提供免费标准送货。快送、定时或定制商品的选项与时效依商品和地址而定，结账页及原订单显示具体安排；预计时间不是无条件到货承诺。本站体验订单不共享 Apple 的配送服务。','APPLE','SHIPPING','apple-shipping','https://www.apple.com.cn/shop/help/shipping_delivery','Apple 官方商店发货与交货','2026-11-17','中国大陆 Apple 在线商店配送订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10005','退换货','小米商城售后退换货政策','小米 米家 Xiaomi Redmi 红米 退货 换货 无理由 冰箱 洗衣机 手机','小米商城售后政策按品类区分无理由退货与质量问题退换修。应核对购买渠道、型号、收货日期、商品完好情况及原包装等条件，不能把手机规则直接用于冰箱、洗衣机或线下订单。具体退货限制以对应品类官方政策为准。','XIAOMI','RETURNS','xiaomi-returns','https://www.mi.com/c/service/exchange','小米商城售后退换货政策','2026-11-17','中国大陆品牌官方线上渠道；须核对具体订单与商品条件','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10006','保修','小米米家分类保修说明','小米 米家 红米 Redmi 保修 质保 维修 三包 冰箱 空调 洗衣机','小米售后服务按商品品类列示保修与三包要求，部分商品由厂家提供服务且期限存在差异。查询米家冰箱、空调或洗衣机时应提供具体型号、购买日期和故障信息，不能用统一的一年期限替代整机与主要部件条款。','XIAOMI','WARRANTY','xiaomi-warranty','https://www.mi.com/c/service/exchange','小米米家分类保修说明','2026-11-17','中国大陆品牌官方线上渠道；须核对具体订单与商品条件','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10007','配送','小米商城配送费参考','小米 米家 Redmi 物流 配送 运费 包邮 发货','小米商城运费按商品类别与配送方式区分，部分商品不参与一般包邮活动。配送费用与可选服务应在对应商品和实际结算订单核对，不应将本站满 99 元免基础运费的体验规则说成小米商城通用政策。','XIAOMI','SHIPPING','xiaomi-shipping','https://www.mi.com/service/buy/postage','小米商城配送费参考','2026-11-17','中国大陆品牌官方线上渠道；须核对具体订单与商品条件','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10008','退换货','Nike 中国大陆销售条款与退货','Nike 耐克 跑鞋 退货 换货 无理由 吊牌 定制 运费','Nike 销售条款规定，除定制商品及平台另有说明外，商品保持原购买状态并符合二次销售条件时，可在收货后 7 天内无理由退货。标签、使用或清洗情况、包装配件及商品页例外均须核对；寄回方式和运费按原耐克平台政策处理。','NIKE','RETURNS','nike-returns','https://agreementservice.svs.nike.com.cn/rest/agreement?agreementType=termsOfSale&country=CN&language=zh&requestType=redirect&uxId=com.nike.tos','Nike 中国大陆销售条款与退货','2026-11-17','中国大陆 Nike 对应官方线上平台订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10009','退款','Nike 订单退款说明','Nike 耐克 退款 到账 原路 质检','Nike 对退回包裹验收并确认符合退货政策后处理退款。取消订单与退货退款属于不同流程，退款时点、支付方式及实际到账需在原 Nike 订单和帮助页核对，不能仅凭申请提交就说已经到账。','NIKE','REFUND','nike-refund','https://www.nike.com.cn/help/a/refund-info-cn','Nike 订单退款说明','2026-11-17','中国大陆 Nike.com.cn、Nike App、SNKRS 或官方微信小程序对应订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10010','配送','Nike 会员配送服务','Nike 耐克 会员 配送 发货 运费 包邮','Nike 会员页提供线上会员订单的免费配送权益，退换货仍需满足相应政策，定制商品另有限制。应确认用户是否为适用会员以及订单所处官方渠道；不能据此保证所有非会员、其他平台或本站订单免邮。','NIKE','SHIPPING','nike-shipping','https://www.nike.com.cn/membership/delivery','Nike 会员配送服务','2026-11-17','Nike 官方会员页列明的线上订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10011','退换货','宜家中国大陆退货政策','IKEA 宜家 退货 换货 无理由 会员 食品 电器','宜家退货窗口为 60 天，宜家俱乐部会员为 365 天，须满足货品完好并提供原始购买凭证及已开具发票等要求。食品、家用电器及特定定制或已加工商品有例外，不能把会员窗口说成所有商品无条件可退。','IKEA','RETURNS','ikea-returns','https://www.ikea.cn/cn/zh/customer-service/returns-claims/return-policy/','宜家中国大陆退货政策','2026-11-17','宜家政策列明的中国大陆门店、官网、App、小程序及天猫渠道','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10012','保修','宜家品质保证分类说明','IKEA 宜家 保修 质保 品质保证 家具 床垫 凭证','宜家品质保证按产品系列分别列示，并从购买日起算，索赔时需原始购买凭证。床垫、家具与其他产品的保证范围及期限不同，须查看具体产品的完整保证书；不能把某系列的十年保证推广到所有宜家商品。','IKEA','WARRANTY','ikea-warranty','https://www.ikea.cn/cn/zh/customer-service/returns-claims/guarantee/','宜家品质保证分类说明','2026-11-17','宜家品质保证列表和各系列完整保证书列明的产品','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10013','配送','宜家中国大陆送货服务','IKEA 宜家 配送 运费 送货 快递 家具 大件','宜家区分包裹配送与货车配送，商品价格不含额外配送费用。包裹适用重量、外包装尺寸及品类限制，家具等大件按地址和服务方式核算。请在原宜家购物车输入地址核对费用和安排；本站不会按该资料自动计算运费。','IKEA','SHIPPING','ikea-shipping','https://www.ikea.cn/cn/zh/customer-service/services/delivery/','宜家中国大陆送货服务','2026-11-17','中国大陆宜家送货服务覆盖地区和适用商品','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10014','退换货','无印良品官方网络商城退换货','MUJI 无印良品 無印良品 退货 换货 无理由 标签 包装','无印良品官方网络商城提供自签收日起 14 日内的符合条件退换货服务，非质量问题需不影响再次销售；标签、包装、配件和商品状况有要求。实体店、官网、京东及天猫等渠道不接受相互出售商品的退换货，不能跨渠道套用。','MUJI','RETURNS','muji-returns','https://www.muji.com.cn/cn/net/contents/contact/return/','无印良品官方网络商城退换货','2026-11-17','无印良品中国大陆官方网络商城对应订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10015','退款','无印良品网络商城退款流程','MUJI 无印良品 退款 到账 退货 物流 审核','退货退款需要提交申请、商家审核、寄回与上传物流、仓库验收等步骤；仅退款有另一套适用订单流程。页面说明审核与退款处理时点，但不能把提交申请等同退款完成，应在原订单售后详情核对进度。','MUJI','REFUND','muji-refund','https://www.muji.com.cn/cn/net/contents/contact/return/','无印良品网络商城退款流程','2026-11-17','无印良品中国大陆官方网络商城对应订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10016','配送','无印良品官方网络商城配送说明','MUJI 无印良品 配送 运费 发货 包邮 大件','MUJI 官网配送说明区分小件与大件，区域、件数和商品类型影响运费；大陆以外地区及特定液体、粉尘商品存在配送限制。具体费用以实际商品和结算页面为准，不将其他渠道的包邮活动当作通用承诺。','MUJI','SHIPPING','muji-shipping','https://www.muji.com.cn/cn/net/contents/contact/delivery/','无印良品官方网络商城配送说明','2026-11-17','无印良品中国大陆官方网络商城适用配送订单','CN_MAINLAND','summary-2026-11-17','仅适用于本文列明的品牌、地区和购买渠道；不能据此自动认定本站订单符合退换修条件。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10017','退换货','沃沃智购体验商城售后办理','退货 换货 退款 售后 申请 订单','本站目前对符合后端状态及归属校验的订单提供售后预检和确认申请，申请成功进入 REVIEWING，并不是真实退款。品牌官方渠道政策不能自动决定本站订单资格；请提供本人订单号和申请类型。','PLATFORM','RETURNS','platform-returns',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10018','退款','沃沃智购体验退款边界','退款 到账 原路 审核','当前只记录售后申请及审核中状态，没有接入真实退款渠道，因此不能承诺到账时间或声称款项已退回。查询本人售后记录需使用后端状态。','PLATFORM','REFUND','platform-refund',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10019','配送','沃沃智购体验配送与运费','配送 运费 包邮 发货 物流','本站试算按当前服务规则计算运费：商品优惠后金额满 99 元免基础运费，否则 8 元。预计配送日期为演示信息，不表示品牌承运或真实发货；实际物流只读取本库订单轨迹。','PLATFORM','SHIPPING','platform-shipping',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10020','订单','沃沃智购待付款订单取消规则','取消 支付 付款 订单','当前普通取消接口只支持待付款订单；已支付等其他状态不能用该接口直接取消。新订单默认 15 分钟未付款自动关闭，取消或关闭以数据库处理结果为准。','PLATFORM','ORDER','platform-order',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10021','优惠','沃沃智购优惠券使用规则','优惠 优惠券 领券 满减','本站订单每笔限用一张满足有效期和金额门槛的用户券，优惠与运费通过后端试算核对。本站优惠券不代表 Apple、Nike 等品牌官方优惠，也不会与品牌订单共享。','PLATFORM','COUPON','platform-coupon',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
INSERT INTO knowledge_document(id,category,title,keywords,content,brand_code,document_type,document_key,source_url,source_name,source_checked_at,applicable_channel,region,content_version,scope_note) VALUES ('10022','保修','沃沃智购品牌保修查询说明','保修 质保 维修 三包','本项目没有为全部品牌制定统一的硬件保修年限。请补充品牌、型号、购买地区、日期与渠道，再查看适用的品牌官方条款。','PLATFORM','WARRANTY','platform-warranty',NULL,'沃沃智购当前实现与服务契约','2026-11-17','沃沃智购本项目体验商城','CN_MAINLAND','summary-2026-11-17','本站体验规则；并未接入真实支付、退款或品牌履约。');
