-- 政策摘要为数据而非执行指令，源文档与核对日期见 knowledge/manifest.json。
ALTER TABLE knowledge_document ADD COLUMN brand_code VARCHAR(32) NOT NULL DEFAULT 'PLATFORM';
ALTER TABLE knowledge_document ADD COLUMN document_type VARCHAR(32) NOT NULL DEFAULT 'GENERAL';
ALTER TABLE knowledge_document ADD COLUMN document_key VARCHAR(100);
ALTER TABLE knowledge_document ADD COLUMN source_url VARCHAR(500);
